    def f(n,m,k, fact, inv_fact):
        MOD=10**9+7
        if n==1:
            return m%MOD if k==0 else 0
        if k<0 or k>=n:
            return 0
        if m==1:
            return 1 if k==n-1 else 0
        return comb(n-1,k,fact,inv_fact)*m%MOD*pow(m-1, n-k-1, MOD)%MOD

    maxn=100000
    fact=[1]*(maxn+1)
    for i in range(1,maxn+1):
        fact[i]=fact[i-1]*i%MOD
    inv_fact=[1]*(maxn+1)
    inv_fact[maxn]=pow(fact[maxn], MOD-2, MOD)
    for i in range(maxn,0,-1):
        inv_fact[i-1]=inv_fact[i]*i%MOD

    ok=True
    for (n,m,k), exp in expected_vals.items():
        val=f(n,m,k,fact,inv_fact)
        if val != exp:
            print(f"MISMATCH {n},{m},{k} => {val} expected {exp}")
            ok=False
    if ok:
        print("All expected match formula!")

    import itertools

    def brute(n,m,k):
        cnt=0
        for arr in itertools.product(range(1,m+1), repeat=n):
            eq=sum(1 for i in range(1,n) if arr[i-1]==arr[i])
            if eq==k:
                cnt+=1
        return cnt

    for n in range(1,5):
